import { execFileSync } from 'node:child_process';
import { parseArgs } from 'node:util';
import { writeFileSync } from 'node:fs';
import fc from 'fast-check';
import { historyProperties } from './history.mjs';
import { queueProperties } from './queue.mjs';

// No provider, credential, model, or network dependency: only production APIs
// and fast-check. JSON on stdout is the durable replay/evaluation artifact.
try {
  const { values } = parseArgs({
    options: {
      target: { type: 'string', default: 'all' },
      property: { type: 'string' },
      seed: { type: 'string' },
      path: { type: 'string' },
      runs: { type: 'string', default: '1000' },
      output: { type: 'string' },
      help: { type: 'boolean' },
    },
  });
  if (values.help) {
    console.log(
      'pnpm verify:generated [--target all|history|queue] [--property NAME] [--runs N] [--seed INT] [--path SHRINK_PATH] [--output FILE]',
    );
  } else {
    const runs = Number(values.runs);
    const seed = values.seed === undefined ? undefined : Number(values.seed);
    if (
      !Number.isSafeInteger(runs) ||
      runs < 1 ||
      (seed !== undefined && (!Number.isInteger(seed) || seed < -2147483648 || seed > 2147483647))
    )
      throw new Error('runs must be a positive safe integer; seed must be int32');
    if (!['all', 'history', 'queue'].includes(values.target)) throw new Error('unknown target');
    let properties =
      values.target === 'history'
        ? historyProperties
        : values.target === 'queue'
        ? queueProperties
        : [...historyProperties, ...queueProperties];
    if (values.property) properties = properties.filter((p) => p.name === values.property);
    if (!properties.length) throw new Error('unknown property for target');
    if (values.path !== undefined && (properties.length !== 1 || seed === undefined))
      throw new Error('replay path requires --property and --seed');
    const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim();
    const revision = git('rev-parse', 'HEAD');
    const dirty = git('status', '--porcelain').length > 0;
    const started = performance.now();
    const results = [];
    for (const { name, property } of properties) {
      const start = performance.now();
      const result = await fc.check(property, {
        numRuns: runs,
        ...(seed === undefined ? {} : { seed }),
        ...(values.path === undefined ? {} : { path: values.path }),
      });
      results.push({
        property: name,
        failed: result.failed,
        seed: result.seed,
        path: result.counterexamplePath,
        cases: result.numRuns,
        skips: result.numSkips,
        shrinks: result.numShrinks,
        runtimeMs: performance.now() - start,
        counterexample: result.counterexample,
        error: result.errorInstance ? String(result.errorInstance.stack ?? result.errorInstance) : null,
        replay: result.failed
          ? `pnpm verify:generated --property ${name} --seed ${result.seed} --path '${result.counterexamplePath}' --runs ${runs}`
          : null,
      });
    }
    const report = {
      schemaVersion: 1,
      revision,
      dirty,
      node: process.version,
      requestedRunsPerProperty: runs,
      maxSequenceLength: 30,
      runtimeMs: performance.now() - started,
      results,
    };
    const json = JSON.stringify(report, null, 2) + '\n';
    if (values.output) writeFileSync(values.output, json, { flag: 'wx' });
    process.stdout.write(json);
    if (results.some((r) => r.failed)) process.exitCode = 1;
  }
} catch (error) {
  console.error(String(error.stack ?? error));
  process.exitCode = 2;
}
import assert from 'node:assert/strict';
import fc from 'fast-check';
import { projectProviderHistory } from '../../source/services/conversation/conversation-state-projector.ts';

// projectProviderHistory's contract: stateless, non-mutating, idempotent;
// dropUnpairedFunctionCalls: retain complete pairs, discard orphan sides.
export const historyProperties = [
  {
    name: 'history.pair-projection',
    property: fc.property(
      fc.array(fc.record({ paired: fc.boolean(), output: fc.string(), arguments: fc.jsonValue() }), { maxLength: 30 }),
      (entries) => {
        const history = entries.flatMap((entry, index) => [
          {
            type: 'function_call',
            call_id: `call-${index}`,
            name: 'probe',
            arguments: JSON.stringify(entry.arguments),
          },
          ...(entry.paired ? [{ type: 'function_call_output', call_id: `call-${index}`, output: entry.output }] : []),
        ]);
        history.push({ type: 'function_call_output', call_id: 'orphan', output: '' });
        const before = structuredClone(history);
        const projected = projectProviderHistory({ history });
        assert.deepEqual(history, before, 'projection mutated input');
        const expected = before.filter(
          (item) => item.call_id !== 'orphan' && entries[Number(item.call_id.slice(5))].paired,
        );
        assert.deepEqual(projected.history, expected, 'complete pairs changed or orphan survived');
        assert.deepEqual(
          projectProviderHistory({ history: projected.history }).history,
          projected.history,
          'not idempotent',
        );
      },
    ),
  },
];

import assert from 'node:assert/strict';
import fc from 'fast-check';
import { QueueController } from '../../source/services/queue/queue-controller.ts';

// A serial reference model for the public follow-up queue lane: FIFO dispatch,
// failure pauses retained work; removing/discarding all retained work releases
// the pause (see #cancel and interrupted-active restoration's empty-pause invariant).
const action = fc.oneof(
  fc.record({
    kind: fc.constant('submit'),
    text: fc.string({ minLength: 1, maxLength: 30 }).filter((s) => !!s.trim()),
  }),
  fc.record({
    kind: fc.constantFrom('complete', 'fail', 'remove', 'edit', 'resume', 'discard', 'stale'),
    index: fc.nat(30),
  }),
);
export const queueProperties = [
  {
    name: 'queue.restore-pause',
    property: fc.asyncProperty(
      fc.constantFrom('failure', 'manual', 'recovered_interrupted'),
      fc.array(
        fc.string({ minLength: 1, maxLength: 30 }).filter((s) => !!s.trim()),
        { maxLength: 30 },
      ),
      async (reason, texts) => {
        const queue = texts.map((text, index) => ({
          id: `saved-${index}`,
          text,
          sequence: index + 1,
          submittedAt: '2026-01-01T00:00:00.000Z',
        }));
        const starts = [];
        const controller = new QueueController({
          driver: {
            start: (execution) => {
              starts.push(execution.item.text);
            },
            cancel: () => true,
          },
          snapshotFactory: (item) => ({ text: item.text }),
          persistence: {
            load: () => ({ version: 1, nextSequence: queue.length + 1, queue, pause: { reason } }),
            replace: () => {},
          },
        });
        assert.equal(controller.state().kind, queue.length ? 'paused' : 'idle');
        assert.deepEqual(
          controller.state().queue.map(({ text }) => text),
          texts,
        );
        assert.deepEqual(starts, []);
        await controller.command({ kind: 'submit', text: 'fresh input' });
        assert.deepEqual(starts, queue.length ? [] : ['fresh input']);
        if (queue.length) assert.equal(controller.state().reason, reason);
      },
    ),
  },
  {
    name: 'queue.serial-actions',
    property: fc.asyncProperty(fc.array(action, { maxLength: 30 }), async (actions) => {
      let next = 0;
      let execution = 0;
      let previousExecutionId;
      const starts = [];
      const controller = new QueueController({
        driver: {
          start: (execution) => {
            starts.push({ id: execution.item.id, text: execution.item.text, snapshotText: execution.snapshot.text });
          },
          cancel: () => true,
        },
        snapshotFactory: (item) => ({ text: item.text }),
        ids: { item: () => `item-${++next}`, execution: () => `execution-${++execution}` },
        now: () => '2026-01-01T00:00:00.000Z',
        capacity: 100,
      });
      const model = { active: null, queue: [], paused: false, starts: [] };
      const dispatch = () => {
        if (!model.active && !model.paused && model.queue.length) {
          model.active = model.queue.shift();
          model.starts.push({ ...model.active, snapshotText: model.active.text });
        }
      };
      for (const [step, action] of actions.entries()) {
        const state = controller.state();
        switch (action.kind) {
          case 'submit': {
            assert.equal((await controller.command({ kind: 'submit', text: action.text })).kind, 'accepted');
            model.queue.push({ id: `item-${next}`, text: action.text });
            dispatch();
            break;
          }
          case 'complete':
          case 'fail':
            if (model.active) {
              await controller.event({
                kind: action.kind === 'complete' ? 'completed' : 'failed',
                executionId: state.active.executionId,
                terminal: {},
                failure: 'generated',
              });
              previousExecutionId = state.active.executionId;
              model.active = null;
              model.paused = action.kind === 'fail' && model.queue.length > 0;
              dispatch();
            }
            break;
          case 'remove':
          case 'edit':
            if (model.queue.length) {
              const index = action.index % model.queue.length;
              await controller.command({
                kind: action.kind === 'remove' ? 'remove_queued' : 'edit_queued',
                itemId: model.queue[index].id,
                text: 'edited',
              });
              if (action.kind === 'remove') model.queue.splice(index, 1);
              else model.queue[index].text = 'edited';
              if (!model.queue.length) model.paused = false;
            }
            break;
          case 'resume':
            await controller.command({ kind: 'resume_queue' });
            model.paused = false;
            dispatch();
            break;
          case 'discard':
            await controller.command({ kind: 'discard_queue' });
            model.queue = [];
            model.paused = false;
            break;
          case 'stale':
            await controller.event({
              kind: 'completed',
              executionId: previousExecutionId ?? 'never-issued',
              terminal: {},
            });
            break;
        }
        const actual = controller.state();
        assert.deepEqual(
          actual.queue.map(({ id, text }) => ({ id, text })),
          model.queue,
          `queue at step ${step}`,
        );
        assert.deepEqual(
          actual.active ? { id: actual.active.item.id, text: actual.active.item.text } : null,
          model.active,
          `active at step ${step}`,
        );
        assert.equal(actual.kind, model.active ? 'running' : model.paused ? 'paused' : 'idle', `phase at step ${step}`);
        assert.deepEqual(starts, model.starts, `dispatch at step ${step}`);
      }
    }),
  },
];

export type ItemId = string & { readonly __itemId: unique symbol };
export type ExecutionId = string & { readonly __executionId: unique symbol };
export type ActionId = string & { readonly __actionId: unique symbol };

export type QueuePauseReason = 'failure' | 'manual' | 'recovered_interrupted';

export type PreflightKind = 'input_surge' | 'large_uncached_input';
export type ActiveActionKind = 'tool_approval' | 'ask_user';

export type PersistedQueueV1<Snapshot = unknown> = {
  readonly version: 1;
  readonly nextSequence: number;
  readonly queue: readonly PersistedQueueItem[];
  readonly pause?: { readonly reason: QueuePauseReason; readonly detail?: unknown };
  readonly active?: {
    readonly executionId: ExecutionId;
    readonly item: PersistedQueueItem;
    readonly snapshot: Readonly<Snapshot>;
    readonly phase: 'running' | 'awaiting_active_action' | 'cancelling' | 'completing';
    readonly pendingAction?: { readonly actionId: string; readonly kind: ActiveActionKind };
  };
};

/** The backing store must replace a complete record atomically. */
export interface QueuePersistence<Snapshot = unknown> {
  load(): unknown;
  replace(record: PersistedQueueV1<Snapshot>): void | Promise<void>;
  quarantine?(): void | Promise<void>;
}

export type QueueRecovery =
  | { readonly kind: 'recovered_interrupted'; readonly interruptedExecutionId: ExecutionId }
  | { readonly kind: 'invalid_persisted_queue'; readonly detail: string }
  | { readonly kind: 'persistence_failed'; readonly detail: string };

export interface PersistedQueueItem {
  readonly id: string;
  readonly text: string;
  readonly sequence: number;
  readonly submittedAt: string;
  /** Submitted as a steer, so it runs ahead of follow-ups queued before it. */
  readonly steer?: boolean;
  readonly preflight?: { readonly actionId: string; readonly kind: PreflightKind };
}

export interface QueueItem {
  readonly id: ItemId;
  readonly text: string;
  readonly sequence: number;
  readonly submittedAt: string;
  /** Submitted as a steer, so it runs ahead of follow-ups queued before it. */
  readonly steer?: boolean;
  readonly preflight?: { readonly actionId: ActionId; readonly kind: PreflightKind };
}

export interface ActiveExecution<Snapshot> {
  readonly executionId: ExecutionId;
  readonly item: QueueItem;
  readonly snapshot: Readonly<Snapshot>;
}

export type QueueState<Snapshot> =
  | { readonly kind: 'idle'; readonly queue: readonly QueueItem[]; readonly recovery?: QueueRecovery }
  | {
      readonly kind: 'awaiting_preflight';
      readonly queue: readonly QueueItem[];
      readonly head: QueueItem;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'running';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'awaiting_active_action';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly pendingAction: { readonly actionId: ActionId; readonly kind: ActiveActionKind };
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'cancelling';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'completing';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'paused';
      readonly queue: readonly QueueItem[];
      readonly reason: QueuePauseReason;
      readonly recovery?: QueueRecovery;
    };

export type QueueCommand =
  | { readonly kind: 'submit'; readonly text: string; readonly id?: string }
  | { readonly kind: 'steer'; readonly text: string; readonly id?: string }
  | { readonly kind: 'cancel' }
  | { readonly kind: 'cancellation_settled'; readonly executionId: ExecutionId }
  | {
      readonly kind: 'answer_preflight';
      readonly itemId: ItemId;
      readonly actionId: ActionId;
      readonly accepted: boolean;
    }
  | {
      readonly kind: 'resolve_tool_approval';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly approved: boolean;
    }
  | {
      readonly kind: 'answer_ask_user';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly value: string;
    }
  | { readonly kind: 'resume_queue' }
  | { readonly kind: 'discard_queue' }
  | { readonly kind: 'edit_queued'; readonly itemId: ItemId; readonly text: string }
  | { readonly kind: 'remove_queued'; readonly itemId: ItemId }
  | { readonly kind: 'change_execution_settings'; readonly settings: unknown }
  | { readonly kind: 'change_cosmetic_settings'; readonly settings: unknown };

export type TurnEvent<Terminal = unknown> =
  | { readonly kind: 'completed'; readonly executionId: ExecutionId; readonly terminal: Terminal }
  | { readonly kind: 'failed'; readonly executionId: ExecutionId; readonly failure: unknown }
  | {
      readonly kind: 'tool_approval_requested';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly request: unknown;
    }
  | {
      readonly kind: 'ask_user_requested';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly question: unknown;
    };

export type QueueCommandResult =
  | { readonly kind: 'accepted' }
  | {
      readonly kind: 'rejected';
      readonly reason: 'capacity' | 'invalid' | 'not_queued' | 'stale' | 'inapplicable' | 'cancellation_unproven';
    }
  | { readonly kind: 'no_op' };

export interface QueueTurnDriver<Snapshot> {
  start(execution: ActiveExecution<Snapshot>): void | Promise<void>;
  cancel(execution: ActiveExecution<Snapshot>): void | boolean | Promise<void | boolean>;
}

export interface QueueControllerOptions<Snapshot, Terminal = unknown> {
  readonly driver: QueueTurnDriver<Snapshot>;
  readonly snapshotFactory: (item: QueueItem) => Snapshot;
  readonly capacity?: number;
  readonly ids?: { readonly item: () => string; readonly execution: () => string; readonly action?: () => string };
  readonly now?: () => string;
  readonly completionBarrier?: (event: Extract<TurnEvent<Terminal>, { kind: 'completed' }>) => void | Promise<void>;
  readonly persistence?: QueuePersistence<Snapshot>;
  readonly preflightEvaluator?: (item: QueueItem) => { preflight: { actionId: ActionId; kind: PreflightKind } } | null;
}

const freeze = <T>(value: T): Readonly<T> => {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const nested of Object.values(value)) freeze(nested);
  }
  return value;
};

const isNonEmptyString = (value: unknown): value is string => typeof value === 'string' && value.length > 0;

const isPauseReason = (value: unknown): value is QueuePauseReason =>
  value === 'failure' || value === 'manual' || value === 'recovered_interrupted';

const isValidPreflightKind = (value: unknown): value is PreflightKind =>
  value === 'input_surge' || value === 'large_uncached_input';

const isValidActiveActionKind = (value: unknown): value is ActiveActionKind =>
  value === 'tool_approval' || value === 'ask_user';

const isPersistedQueueItem = (value: unknown): value is PersistedQueueItem => {
  if (!value || typeof value !== 'object') return false;
  const item = value as Record<string, unknown>;
  if (
    !isNonEmptyString(item.id) ||
    typeof item.text !== 'string' ||
    !Number.isSafeInteger(item.sequence) ||
    (item.sequence as number) <= 0 ||
    !isNonEmptyString(item.submittedAt) ||
    Number.isNaN(Date.parse(item.submittedAt as string)) ||
    (item.steer !== undefined && typeof item.steer !== 'boolean')
  ) {
    return false;
  }
  if (item.preflight !== undefined) {
    if (
      !item.preflight ||
      typeof item.preflight !== 'object' ||
      !isNonEmptyString((item.preflight as Record<string, unknown>).actionId) ||
      !isValidPreflightKind((item.preflight as Record<string, unknown>).kind)
    ) {
      return false;
    }
  }
  return true;
};

const validatePersistedQueue = <Snapshot>(value: unknown): PersistedQueueV1<Snapshot> | string => {
  if (!value || typeof value !== 'object') return 'record must be an object';
  const record = value as Record<string, unknown>;
  if (record.version !== 1) return 'unsupported queue record version';
  if (!Number.isSafeInteger(record.nextSequence) || (record.nextSequence as number) < 1) return 'invalid next sequence';
  if (!Array.isArray(record.queue) || !(record.queue as unknown[]).every(isPersistedQueueItem))
    return 'invalid queued item';
  const queue = record.queue as PersistedQueueItem[];
  if (queue.some((item, index) => index > 0 && item.sequence <= queue[index - 1]!.sequence)) {
    return 'queue sequences must be strictly increasing';
  }
  if (queue.some((item) => item.sequence >= (record.nextSequence as number)))
    return 'next sequence must exceed queue sequences';
  if (new Set(queue.map((item) => item.id)).size !== queue.length) return 'queue item IDs must be unique';
  if (record.pause !== undefined) {
    if (
      !record.pause ||
      typeof record.pause !== 'object' ||
      !isPauseReason((record.pause as Record<string, unknown>).reason)
    ) {
      return 'invalid pause record';
    }
  }
  if (record.active !== undefined) {
    if (!record.active || typeof record.active !== 'object') return 'invalid active record';
    const active = record.active as Record<string, unknown>;
    if (!isNonEmptyString(active.executionId) || !isPersistedQueueItem(active.item) || !('snapshot' in active))
      return 'invalid active ownership';
    if (!['running', 'awaiting_active_action', 'cancelling', 'completing'].includes(active.phase as string))
      return 'invalid active phase';
    if (active.pendingAction !== undefined) {
      if (
        !active.pendingAction ||
        typeof active.pendingAction !== 'object' ||
        !isNonEmptyString((active.pendingAction as Record<string, unknown>).actionId) ||
        !isValidActiveActionKind((active.pendingAction as Record<string, unknown>).kind)
      ) {
        return 'invalid active action';
      }
    }
    if (queue.some((item) => item.id === (active.item as PersistedQueueItem).id)) return 'active item is also queued';
  }
  return value as PersistedQueueV1<Snapshot>;
};

const persistedItemToQueueItem = (item: PersistedQueueItem): QueueItem =>
  freeze({
    ...item,
    id: item.id as ItemId,
    preflight: item.preflight
      ? { actionId: item.preflight.actionId as ActionId, kind: item.preflight.kind }
      : undefined,
  });

const queueItemToPersisted = (item: QueueItem): PersistedQueueItem => ({
  id: item.id,
  text: item.text,
  sequence: item.sequence,
  submittedAt: item.submittedAt,
  ...(item.steer ? { steer: true } : {}),
  preflight: item.preflight ? { actionId: item.preflight.actionId, kind: item.preflight.kind } : undefined,
});

type InternalPhase =
  | 'idle'
  | 'awaiting_preflight'
  | 'running'
  | 'awaiting_active_action'
  | 'cancelling'
  | 'completing'
  | 'paused';

export class QueueController<Snapshot, Terminal = unknown> {
  readonly #driver: QueueTurnDriver<Snapshot>;
  readonly #snapshotFactory: (item: QueueItem) => Snapshot;
  readonly #capacity: number;
  readonly #itemId: () => string;
  readonly #executionId: () => string;
  readonly #actionId: () => string;
  readonly #now: () => string;
  readonly #completionBarrier?: (event: Extract<TurnEvent<Terminal>, { kind: 'completed' }>) => void | Promise<void>;
  readonly #persistence?: QueuePersistence<Snapshot>;
  readonly #preflightEvaluator?: (item: QueueItem) => { preflight: { actionId: ActionId; kind: PreflightKind } } | null;
  #nextSequence = 1;
  #queue: QueueItem[] = [];
  #phase: InternalPhase = 'idle';
  #active: ActiveExecution<Snapshot> | undefined;
  #pendingAction: { actionId: ActionId; kind: ActiveActionKind } | undefined;
  #pauseReason: QueuePauseReason | undefined;
  #recovery: QueueRecovery | undefined;
  #persistenceWrites = Promise.resolve();
  /** Out-of-band occupancy (manual compaction) that must not start queued work. */
  #dispatchHeld = false;
  #cancellationUnproven = false;
  #cancellationExecutionId: ExecutionId | null = null;
  #cancelRetainedItemIds = new Set<ItemId>();

  constructor(options: QueueControllerOptions<Snapshot, Terminal>) {
    this.#driver = options.driver;
    this.#snapshotFactory = options.snapshotFactory;
    this.#capacity = options.capacity ?? Infinity;
    this.#itemId = options.ids?.item ?? (() => crypto.randomUUID());
    this.#executionId = options.ids?.execution ?? (() => crypto.randomUUID());
    this.#actionId = options.ids?.action ?? (() => crypto.randomUUID());
    this.#now = options.now ?? (() => new Date().toISOString());
    this.#completionBarrier = options.completionBarrier;
    this.#persistence = options.persistence;
    this.#preflightEvaluator = options.preflightEvaluator;
    this.#restore();
  }

  /**
   * Prevent `#dispatch` while idle. Submissions still enqueue. Returns false
   * when the queue is already occupied (running, paused, or already held).
   */
  holdDispatch(): boolean {
    if (this.#dispatchHeld || this.#phase !== 'idle' || this.#active) return false;
    this.#dispatchHeld = true;
    return true;
  }

  isDispatchHeld(): boolean {
    return this.#dispatchHeld;
  }

  /**
   * Drop the hold. By default the next queued item starts. `pauseIfQueued`
   * matches stop-during-a-turn: retained work stays paused instead of running.
   */
  releaseDispatch(options: { pauseIfQueued?: boolean } = {}): void {
    if (!this.#dispatchHeld) return;
    this.#dispatchHeld = false;
    if (options.pauseIfQueued && this.#queue.length > 0 && this.#phase === 'idle' && !this.#active) {
      this.#phase = 'paused';
      this.#pauseReason = 'manual';
      void this.#persist();
      return;
    }
    void this.#dispatch();
  }

  state(): QueueState<Snapshot> {
    const queue = this.#queue.map((item) => ({ ...item }));
    const recovery = this.#recovery ? { recovery: this.#recovery } : {};

    if (this.#phase === 'awaiting_preflight') {
      return freeze({
        kind: 'awaiting_preflight',
        queue,
        head: { ...queue[0]! },
        ...recovery,
      });
    }
    if (this.#phase === 'awaiting_active_action') {
      return freeze({
        kind: 'awaiting_active_action',
        queue,
        active: this.#active!,
        pendingAction: this.#pendingAction!,
        ...recovery,
      });
    }
    if (this.#phase === 'paused') return freeze({ kind: 'paused', queue, reason: this.#pauseReason!, ...recovery });
    if (this.#phase === 'cancelling') return freeze({ kind: 'cancelling', queue, active: this.#active!, ...recovery });
    if (this.#phase === 'completing') return freeze({ kind: 'completing', queue, active: this.#active!, ...recovery });
    if (this.#active) return freeze({ kind: 'running', queue, active: this.#active, ...recovery });
    return freeze({ kind: 'idle', queue, ...recovery });
  }

  async command(cmd: QueueCommand): Promise<QueueCommandResult> {
    switch (cmd.kind) {
      case 'submit':
        return this.#submit(cmd);
      case 'steer':
        return this.#submit(cmd);
      case 'cancel':
        return this.#cancel();
      case 'cancellation_settled': {
        if (
          this.#phase !== 'cancelling' ||
          !this.#cancellationUnproven ||
          this.#active?.executionId !== cmd.executionId ||
          this.#cancellationExecutionId !== cmd.executionId
        ) {
          return { kind: 'no_op' };
        }
        this.#active = undefined;
        this.#pendingAction = undefined;
        this.#cancellationUnproven = false;
        this.#cancellationExecutionId = null;
        if (this.#cancelRetainedItemIds.size === 0) {
          this.#phase = 'idle';
          this.#pauseReason = undefined;
        } else {
          this.#phase = 'paused';
          this.#pauseReason = 'manual';
        }
        this.#cancelRetainedItemIds.clear();
        await this.#persist();
        if (this.#phase === 'idle') await this.#dispatch();
        return { kind: 'accepted' };
      }
      case 'answer_preflight': {
        if (this.#phase !== 'awaiting_preflight') return { kind: 'rejected', reason: 'stale' };
        const head = this.#queue[0]!;
        if (head.id !== cmd.itemId || head.preflight?.actionId !== cmd.actionId) {
          return { kind: 'rejected', reason: 'stale' };
        }
        if (!cmd.accepted) {
          this.#queue.shift();
          this.#phase = 'idle';
          await this.#persist();
          await this.#dispatch();
          return { kind: 'accepted' };
        }
        return this.#acceptPreflight();
      }
      case 'resolve_tool_approval': {
        if (this.#phase !== 'awaiting_active_action') return { kind: 'rejected', reason: 'stale' };
        if (
          this.#active!.executionId !== cmd.executionId ||
          this.#pendingAction!.actionId !== cmd.actionId ||
          this.#pendingAction!.kind !== 'tool_approval'
        ) {
          return { kind: 'rejected', reason: 'stale' };
        }
        return this.#resolveAction();
      }
      case 'answer_ask_user': {
        if (this.#phase !== 'awaiting_active_action') return { kind: 'rejected', reason: 'stale' };
        if (
          this.#active!.executionId !== cmd.executionId ||
          this.#pendingAction!.actionId !== cmd.actionId ||
          this.#pendingAction!.kind !== 'ask_user'
        ) {
          return { kind: 'rejected', reason: 'stale' };
        }
        return this.#resolveAction();
      }
      case 'resume_queue':
        if (this.#phase !== 'paused') return { kind: 'no_op' };
        this.#phase = 'idle';
        this.#pauseReason = undefined;
        await this.#persist();
        await this.#dispatch();
        return { kind: 'accepted' };
      case 'discard_queue':
        this.#queue = [];
        if (this.#phase === 'cancelling') {
          // Discarding retained work during cancellation changes the stop's
          // effective retention decision, but never releases active ownership.
          this.#cancelRetainedItemIds.clear();
        }
        this.#releaseEmptyPause();
        await this.#persist();
        return { kind: 'accepted' };
      case 'edit_queued': {
        const index = this.#queue.findIndex((item) => item.id === cmd.itemId);
        if (index < 0 || !cmd.text.trim()) return { kind: 'rejected', reason: index < 0 ? 'not_queued' : 'invalid' };
        this.#queue[index] = freeze({ ...this.#queue[index], text: cmd.text });
        await this.#persist();
        return { kind: 'accepted' };
      }
      case 'remove_queued': {
        const index = this.#queue.findIndex((item) => item.id === cmd.itemId);
        if (index < 0) return { kind: 'rejected', reason: 'not_queued' };
        this.#queue.splice(index, 1);
        this.#releaseEmptyPause();
        if (this.#phase === 'cancelling') {
          this.#cancelRetainedItemIds.delete(cmd.itemId);
        }
        if (this.#phase === 'awaiting_preflight' && index === 0) {
          this.#phase = 'idle';
        }
        await this.#persist();
        if (this.#phase === 'idle') {
          await this.#dispatch();
        }
        return { kind: 'accepted' };
      }
      case 'change_execution_settings':
      case 'change_cosmetic_settings':
        await this.#persist();
        return { kind: 'accepted' };
    }
  }

  async #submit(cmd: Extract<QueueCommand, { kind: 'submit' | 'steer' }>): Promise<QueueCommandResult> {
    if (!cmd.text.trim()) return { kind: 'rejected', reason: 'invalid' };
    if (this.#queue.length >= this.#capacity) return { kind: 'rejected', reason: 'capacity' };
    const id = cmd.id ?? this.#itemId();
    if (!isNonEmptyString(id) || this.#queue.some((item) => item.id === id) || this.#active?.item.id === id) {
      return { kind: 'rejected', reason: 'invalid' };
    }
    const item = freeze({
      id: id as ItemId,
      text: cmd.text,
      sequence: this.#nextSequence++,
      submittedAt: this.#now(),
      ...(cmd.kind === 'steer' ? { steer: true as const } : {}),
    });
    if (cmd.kind === 'steer') {
      // A steer that reaches the queue could not be delivered into the running
      // turn, so it runs as its own turn — ahead of the follow-ups queued
      // before it, which is the priority the user expressed by steering, and
      // behind steers they sent earlier, which is the order they said it in.
      const firstFollowUp = this.#queue.findIndex((queued) => !queued.steer);
      const insertAt = firstFollowUp < 0 ? this.#queue.length : firstFollowUp;
      this.#queue = [...this.#queue.slice(0, insertAt), item, ...this.#queue.slice(insertAt)].map((queued) =>
        freeze({ ...queued, sequence: this.#nextSequence++ }),
      );
      await this.#persist();
      await this.#dispatch();
      return { kind: 'accepted' };
    }
    this.#queue.push(item);
    await this.#persist();
    await this.#dispatch();
    return { kind: 'accepted' };
  }

  async event(event: TurnEvent<Terminal>): Promise<void> {
    if (event.kind === 'tool_approval_requested' || event.kind === 'ask_user_requested') {
      if (!this.#active || this.#active.executionId !== event.executionId || this.#phase !== 'running') return;
      this.#pendingAction = {
        actionId: event.actionId,
        kind: event.kind === 'tool_approval_requested' ? 'tool_approval' : 'ask_user',
      };
      this.#phase = 'awaiting_active_action';
      await this.#persist();
      return;
    }

    if (!this.#active || this.#active.executionId !== event.executionId) return;

    const activeFromPhase = this.#phase === 'running' || this.#phase === 'awaiting_active_action';
    if (!activeFromPhase) return;

    if (event.kind === 'failed') {
      this.#active = undefined;
      this.#pendingAction = undefined;
      // Failure policy: do not auto-advance. Pause with retained work so the
      // user can resume or discard; only return to idle when nothing remains.
      if (this.#queue.length === 0) {
        this.#phase = 'idle';
        this.#pauseReason = undefined;
      } else {
        this.#phase = 'paused';
        this.#pauseReason = 'failure';
      }
      await this.#persist();
      return;
    }
    if (event.kind !== 'completed') return;

    this.#pendingAction = undefined;
    this.#phase = 'completing';
    await this.#persist();
    await this.#completionBarrier?.(event);
    if (this.#phase !== 'completing' || this.#active?.executionId !== event.executionId) return;
    this.#active = undefined;
    this.#phase = 'idle';
    await this.#persist();
    await this.#dispatch();
  }

  async #resolveAction(): Promise<QueueCommandResult> {
    this.#phase = 'running';
    this.#pendingAction = undefined;
    await this.#persist();
    return { kind: 'accepted' };
  }

  async #acceptPreflight(): Promise<QueueCommandResult> {
    const item = this.#queue.shift()!;
    const active = freeze({
      executionId: this.#executionId() as ExecutionId,
      item,
      snapshot: freeze(structuredClone(this.#snapshotFactory(item))),
    });
    this.#active = active;
    this.#phase = 'running';
    await this.#persist();
    // Driver failure is handled by the 'failed' event handler (line ~473), not by
    // synchronous exceptions here. The driver returns void and kicks off async work.
    await this.#driver.start(active);
    return { kind: 'accepted' };
  }

  async #cancel(): Promise<QueueCommandResult> {
    if (this.#phase === 'paused' && this.#pauseReason === 'manual') {
      this.#phase = 'idle';
      this.#pauseReason = undefined;
      await this.#persist();
      await this.#dispatch();
      return { kind: 'accepted' };
    }
    if (this.#phase === 'awaiting_preflight') {
      this.#phase = 'paused';
      this.#pauseReason = 'manual';
      await this.#persist();
      return { kind: 'accepted' };
    }
    if (!this.#active || (this.#phase !== 'running' && this.#phase !== 'awaiting_active_action')) {
      if (this.#phase !== 'cancelling') return { kind: 'no_op' };
      return { kind: 'no_op' };
    }
    const active = this.#active;
    // Capture which work was already queued when the user stopped. A manual
    // pause exists only to retain that pre-existing work; items submitted
    // after the stop (including ones raced in while cancel cleanup awaits the
    // active turn) reflect fresh intent and must run, not stick behind an
    // empty pause with nothing to resume.
    this.#cancelRetainedItemIds = new Set(this.#queue.map((item) => item.id));
    this.#phase = 'cancelling';
    this.#cancellationUnproven = false;
    this.#cancellationExecutionId = active.executionId;
    this.#pendingAction = undefined;
    await this.#persist();
    let proven = true;
    try {
      proven = (await this.#driver.cancel(active)) !== false;
    } finally {
      if (this.#active?.executionId === active.executionId && proven) {
        this.#active = undefined;
        this.#cancellationExecutionId = null;
        // Invariant: a paused queue must contain retained work. When nothing
        // remains from stop time, return to idle so the next submission
        // starts immediately instead of being queued behind a manual pause
        // with nothing to resume. A submission raced in during cleanup is
        // dispatched below.
        if (this.#cancelRetainedItemIds.size === 0) {
          this.#phase = 'idle';
          this.#pauseReason = undefined;
        } else {
          this.#phase = 'paused';
          this.#pauseReason = 'manual';
        }
        this.#cancelRetainedItemIds.clear();
        await this.#persist();
        if (this.#phase === 'idle') {
          await this.#dispatch();
        }
      } else if (!proven) {
        // Keep the active execution attached to the cancelling controller.
        // A caller that cannot prove cancellation must not observe an idle
        // queue capable of dispatching work alongside it.
        this.#cancellationUnproven = true;
        await this.#persist();
      }
    }
    return proven ? { kind: 'accepted' } : { kind: 'rejected', reason: 'cancellation_unproven' };
  }

  async #dispatch(): Promise<void> {
    if (this.#dispatchHeld || this.#phase !== 'idle' || this.#active || this.#queue.length === 0) return;

    const head = this.#queue[0]!;

    // If the head already has a preflight (e.g. recovered), respect it.
    if (head.preflight) {
      this.#phase = 'awaiting_preflight';
      await this.#persist();
      return;
    }

    const preflight = this.#preflightEvaluator?.(head)?.preflight;
    if (preflight) {
      this.#queue[0] = freeze({ ...head, preflight: { actionId: preflight.actionId, kind: preflight.kind } });
      this.#phase = 'awaiting_preflight';
      await this.#persist();
      return;
    }

    const item = this.#queue.shift()!;
    const active = freeze({
      executionId: this.#executionId() as ExecutionId,
      item,
      snapshot: freeze(structuredClone(this.#snapshotFactory(item))),
    });
    this.#active = active;
    this.#phase = 'running';
    await this.#persist();
    // Driver failure is handled by the 'failed' event handler (line ~473), not by
    // synchronous exceptions here. The driver returns void and kicks off async work.
    await this.#driver.start(active);
  }

  #restore(): void {
    if (!this.#persistence) return;
    let raw: unknown;
    try {
      raw = this.#persistence.load();
    } catch (error) {
      this.#recovery = {
        kind: 'invalid_persisted_queue',
        detail: error instanceof Error ? error.message : String(error),
      };
      void this.#quarantine();
      return;
    }
    if (raw === null || raw === undefined) return;
    const record = validatePersistedQueue<Snapshot>(raw);
    if (typeof record === 'string') {
      this.#recovery = { kind: 'invalid_persisted_queue', detail: record };
      void this.#quarantine();
      return;
    }
    this.#nextSequence = record.nextSequence;
    this.#queue = record.queue.map((item) => {
      const queueItem = persistedItemToQueueItem(item);
      if (queueItem.preflight && !this.#preflightEvaluator) {
        return freeze({
          ...queueItem,
          preflight: {
            actionId: this.#actionId() as ActionId,
            kind: queueItem.preflight.kind,
          },
        });
      }
      return queueItem;
    });
    if (record.active) {
      // The interrupted active item is dropped, never replayed (C12.3): no
      // driver start, no tool/approval re-dispatch. Its execution id survives
      // only as a recovery diagnostic. When no queued work was retained, settle
      // idle rather than an empty paused controller that would block the
      // composer behind "0 item(s) pending" (C12.4).
      this.#recovery = { kind: 'recovered_interrupted', interruptedExecutionId: record.active.executionId };
      if (this.#queue.length > 0) {
        this.#phase = 'paused';
        this.#pauseReason = 'recovered_interrupted';
      }
      return;
    }
    if (record.pause) {
      this.#phase = 'paused';
      this.#pauseReason = record.pause.reason;
      this.#releaseEmptyPause();
      return;
    }
    if (this.#queue.length > 0) {
      this.#phase = 'paused';
      this.#pauseReason = 'recovered_interrupted';
    }
  }

  /** A pause retains queued work, never active cancellation ownership. */
  #releaseEmptyPause(): void {
    if (this.#phase !== 'paused' || this.#queue.length > 0) return;
    this.#phase = 'idle';
    this.#pauseReason = undefined;
  }

  async #persist(): Promise<void> {
    if (!this.#persistence) return;
    const active = this.#active
      ? {
          executionId: this.#active.executionId,
          item: queueItemToPersisted(this.#active.item),
          snapshot: this.#active.snapshot,
          phase: this.#phase as 'running' | 'awaiting_active_action' | 'cancelling' | 'completing',
          ...(this.#pendingAction
            ? {
                pendingAction: {
                  actionId: this.#pendingAction.actionId,
                  kind: this.#pendingAction.kind,
                },
              }
            : {}),
        }
      : undefined;
    const record: PersistedQueueV1<Snapshot> = {
      version: 1,
      nextSequence: this.#nextSequence,
      queue: this.#queue.map((item) => queueItemToPersisted(item)),
      ...(this.#phase === 'paused' ? { pause: { reason: this.#pauseReason! } } : {}),
      ...(active ? { active } : {}),
    };
    const write = this.#persistenceWrites.then(() => this.#persistence!.replace(record));
    this.#persistenceWrites = write.then(
      () => undefined,
      () => undefined,
    );
    try {
      await write;
    } catch (error) {
      this.#recovery = { kind: 'persistence_failed', detail: error instanceof Error ? error.message : String(error) };
    }
  }

  async #quarantine(): Promise<void> {
    try {
      await this.#persistence?.quarantine?.();
    } catch {
      // Recovery state already reports the rejected record. Quarantine is best effort.
    }
  }
}

import assert from 'node:assert/strict';
import fc from 'fast-check';
import { QueueController } from '../../source/services/queue/queue-controller.ts';

// A serial reference model for the public follow-up queue lane: FIFO dispatch,
// failure pauses retained work; removing/discarding all retained work releases
// the pause (see #cancel and interrupted-active restoration's empty-pause invariant).
const action = fc.oneof(
  fc.record({
    kind: fc.constant('submit'),
    text: fc.string({ minLength: 1, maxLength: 30 }).filter((s) => !!s.trim()),
  }),
  fc.record({
    kind: fc.constantFrom('complete', 'fail', 'remove', 'edit', 'resume', 'discard', 'stale'),
    index: fc.nat(30),
  }),
);
export const queueProperties = [
  {
    name: 'queue.restore-pause',
    property: fc.asyncProperty(
      fc.constantFrom('failure', 'manual', 'recovered_interrupted'),
      fc.array(
        fc.string({ minLength: 1, maxLength: 30 }).filter((s) => !!s.trim()),
        { maxLength: 30 },
      ),
      async (reason, texts) => {
        const queue = texts.map((text, index) => ({
          id: `saved-${index}`,
          text,
          sequence: index + 1,
          submittedAt: '2026-01-01T00:00:00.000Z',
        }));
        const starts = [];
        const controller = new QueueController({
          driver: {
            start: (execution) => {
              starts.push(execution.item.text);
            },
            cancel: () => true,
          },
          snapshotFactory: (item) => ({ text: item.text }),
          persistence: {
            load: () => ({ version: 1, nextSequence: queue.length + 1, queue, pause: { reason } }),
            replace: () => {},
          },
        });
        assert.equal(controller.state().kind, queue.length ? 'paused' : 'idle');
        assert.deepEqual(
          controller.state().queue.map(({ text }) => text),
          texts,
        );
        assert.deepEqual(starts, []);
        await controller.command({ kind: 'submit', text: 'fresh input' });
        assert.deepEqual(starts, queue.length ? [] : ['fresh input']);
        if (queue.length) assert.equal(controller.state().reason, reason);
      },
    ),
  },
  {
    name: 'queue.serial-actions',
    property: fc.asyncProperty(fc.array(action, { maxLength: 30 }), async (actions) => {
      let next = 0;
      let execution = 0;
      let previousExecutionId;
      const starts = [];
      const controller = new QueueController({
        driver: {
          start: (execution) => {
            starts.push({ id: execution.item.id, text: execution.item.text, snapshotText: execution.snapshot.text });
          },
          cancel: () => true,
        },
        snapshotFactory: (item) => ({ text: item.text }),
        ids: { item: () => `item-${++next}`, execution: () => `execution-${++execution}` },
        now: () => '2026-01-01T00:00:00.000Z',
        capacity: 100,
      });
      const model = { active: null, queue: [], paused: false, starts: [] };
      const dispatch = () => {
        if (!model.active && !model.paused && model.queue.length) {
          model.active = model.queue.shift();
          model.starts.push({ ...model.active, snapshotText: model.active.text });
        }
      };
      for (const [step, action] of actions.entries()) {
        const state = controller.state();
        switch (action.kind) {
          case 'submit': {
            assert.equal((await controller.command({ kind: 'submit', text: action.text })).kind, 'accepted');
            model.queue.push({ id: `item-${next}`, text: action.text });
            dispatch();
            break;
          }
          case 'complete':
          case 'fail':
            if (model.active) {
              await controller.event({
                kind: action.kind === 'complete' ? 'completed' : 'failed',
                executionId: state.active.executionId,
                terminal: {},
                failure: 'generated',
              });
              previousExecutionId = state.active.executionId;
              model.active = null;
              model.paused = action.kind === 'fail' && model.queue.length > 0;
              dispatch();
            }
            break;
          case 'remove':
          case 'edit':
            if (model.queue.length) {
              const index = action.index % model.queue.length;
              await controller.command({
                kind: action.kind === 'remove' ? 'remove_queued' : 'edit_queued',
                itemId: model.queue[index].id,
                text: 'edited',
              });
              if (action.kind === 'remove') model.queue.splice(index, 1);
              else model.queue[index].text = 'edited';
              if (!model.queue.length) model.paused = false;
            }
            break;
          case 'resume':
            await controller.command({ kind: 'resume_queue' });
            model.paused = false;
            dispatch();
            break;
          case 'discard':
            await controller.command({ kind: 'discard_queue' });
            model.queue = [];
            model.paused = false;
            break;
          case 'stale':
            await controller.event({
              kind: 'completed',
              executionId: previousExecutionId ?? 'never-issued',
              terminal: {},
            });
            break;
        }
        const actual = controller.state();
        assert.deepEqual(
          actual.queue.map(({ id, text }) => ({ id, text })),
          model.queue,
          `queue at step ${step}`,
        );
        assert.deepEqual(
          actual.active ? { id: actual.active.item.id, text: actual.active.item.text } : null,
          model.active,
          `active at step ${step}`,
        );
        assert.equal(actual.kind, model.active ? 'running' : model.paused ? 'paused' : 'idle', `phase at step ${step}`);
        assert.deepEqual(starts, model.starts, `dispatch at step ${step}`);
      }
    }),
  },
];
export type ItemId = string & { readonly __itemId: unique symbol };
export type ExecutionId = string & { readonly __executionId: unique symbol };
export type ActionId = string & { readonly __actionId: unique symbol };

export type QueuePauseReason = 'failure' | 'manual' | 'recovered_interrupted';

export type PreflightKind = 'input_surge' | 'large_uncached_input';
export type ActiveActionKind = 'tool_approval' | 'ask_user';

export type PersistedQueueV1<Snapshot = unknown> = {
  readonly version: 1;
  readonly nextSequence: number;
  readonly queue: readonly PersistedQueueItem[];
  readonly pause?: { readonly reason: QueuePauseReason; readonly detail?: unknown };
  readonly active?: {
    readonly executionId: ExecutionId;
    readonly item: PersistedQueueItem;
    readonly snapshot: Readonly<Snapshot>;
    readonly phase: 'running' | 'awaiting_active_action' | 'cancelling' | 'completing';
    readonly pendingAction?: { readonly actionId: string; readonly kind: ActiveActionKind };
  };
};

/** The backing store must replace a complete record atomically. */
export interface QueuePersistence<Snapshot = unknown> {
  load(): unknown;
  replace(record: PersistedQueueV1<Snapshot>): void | Promise<void>;
  quarantine?(): void | Promise<void>;
}

export type QueueRecovery =
  | { readonly kind: 'recovered_interrupted'; readonly interruptedExecutionId: ExecutionId }
  | { readonly kind: 'invalid_persisted_queue'; readonly detail: string }
  | { readonly kind: 'persistence_failed'; readonly detail: string };

export interface PersistedQueueItem {
  readonly id: string;
  readonly text: string;
  readonly sequence: number;
  readonly submittedAt: string;
  /** Submitted as a steer, so it runs ahead of follow-ups queued before it. */
  readonly steer?: boolean;
  readonly preflight?: { readonly actionId: string; readonly kind: PreflightKind };
}

export interface QueueItem {
  readonly id: ItemId;
  readonly text: string;
  readonly sequence: number;
  readonly submittedAt: string;
  /** Submitted as a steer, so it runs ahead of follow-ups queued before it. */
  readonly steer?: boolean;
  readonly preflight?: { readonly actionId: ActionId; readonly kind: PreflightKind };
}

export interface ActiveExecution<Snapshot> {
  readonly executionId: ExecutionId;
  readonly item: QueueItem;
  readonly snapshot: Readonly<Snapshot>;
}

export type QueueState<Snapshot> =
  | { readonly kind: 'idle'; readonly queue: readonly QueueItem[]; readonly recovery?: QueueRecovery }
  | {
      readonly kind: 'awaiting_preflight';
      readonly queue: readonly QueueItem[];
      readonly head: QueueItem;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'running';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'awaiting_active_action';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly pendingAction: { readonly actionId: ActionId; readonly kind: ActiveActionKind };
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'cancelling';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'completing';
      readonly queue: readonly QueueItem[];
      readonly active: ActiveExecution<Snapshot>;
      readonly recovery?: QueueRecovery;
    }
  | {
      readonly kind: 'paused';
      readonly queue: readonly QueueItem[];
      readonly reason: QueuePauseReason;
      readonly recovery?: QueueRecovery;
    };

export type QueueCommand =
  | { readonly kind: 'submit'; readonly text: string; readonly id?: string }
  | { readonly kind: 'steer'; readonly text: string; readonly id?: string }
  | { readonly kind: 'cancel' }
  | { readonly kind: 'cancellation_settled'; readonly executionId: ExecutionId }
  | {
      readonly kind: 'answer_preflight';
      readonly itemId: ItemId;
      readonly actionId: ActionId;
      readonly accepted: boolean;
    }
  | {
      readonly kind: 'resolve_tool_approval';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly approved: boolean;
    }
  | {
      readonly kind: 'answer_ask_user';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly value: string;
    }
  | { readonly kind: 'resume_queue' }
  | { readonly kind: 'discard_queue' }
  | { readonly kind: 'edit_queued'; readonly itemId: ItemId; readonly text: string }
  | { readonly kind: 'remove_queued'; readonly itemId: ItemId }
  | { readonly kind: 'change_execution_settings'; readonly settings: unknown }
  | { readonly kind: 'change_cosmetic_settings'; readonly settings: unknown };

export type TurnEvent<Terminal = unknown> =
  | { readonly kind: 'completed'; readonly executionId: ExecutionId; readonly terminal: Terminal }
  | { readonly kind: 'failed'; readonly executionId: ExecutionId; readonly failure: unknown }
  | {
      readonly kind: 'tool_approval_requested';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly request: unknown;
    }
  | {
      readonly kind: 'ask_user_requested';
      readonly executionId: ExecutionId;
      readonly actionId: ActionId;
      readonly question: unknown;
    };

export type QueueCommandResult =
  | { readonly kind: 'accepted' }
  | {
      readonly kind: 'rejected';
      readonly reason: 'capacity' | 'invalid' | 'not_queued' | 'stale' | 'inapplicable' | 'cancellation_unproven';
    }
  | { readonly kind: 'no_op' };

export interface QueueTurnDriver<Snapshot> {
  start(execution: ActiveExecution<Snapshot>): void | Promise<void>;
  cancel(execution: ActiveExecution<Snapshot>): void | boolean | Promise<void | boolean>;
}

export interface QueueControllerOptions<Snapshot, Terminal = unknown> {
  readonly driver: QueueTurnDriver<Snapshot>;
  readonly snapshotFactory: (item: QueueItem) => Snapshot;
  readonly capacity?: number;
  readonly ids?: { readonly item: () => string; readonly execution: () => string; readonly action?: () => string };
  readonly now?: () => string;
  readonly completionBarrier?: (event: Extract<TurnEvent<Terminal>, { kind: 'completed' }>) => void | Promise<void>;
  readonly persistence?: QueuePersistence<Snapshot>;
  readonly preflightEvaluator?: (item: QueueItem) => { preflight: { actionId: ActionId; kind: PreflightKind } } | null;
}

const freeze = <T>(value: T): Readonly<T> => {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const nested of Object.values(value)) freeze(nested);
  }
  return value;
};

const isNonEmptyString = (value: unknown): value is string => typeof value === 'string' && value.length > 0;

const isPauseReason = (value: unknown): value is QueuePauseReason =>
  value === 'failure' || value === 'manual' || value === 'recovered_interrupted';

const isValidPreflightKind = (value: unknown): value is PreflightKind =>
  value === 'input_surge' || value === 'large_uncached_input';

const isValidActiveActionKind = (value: unknown): value is ActiveActionKind =>
  value === 'tool_approval' || value === 'ask_user';

const isPersistedQueueItem = (value: unknown): value is PersistedQueueItem => {
  if (!value || typeof value !== 'object') return false;
  const item = value as Record<string, unknown>;
  if (
    !isNonEmptyString(item.id) ||
    typeof item.text !== 'string' ||
    !Number.isSafeInteger(item.sequence) ||
    (item.sequence as number) <= 0 ||
    !isNonEmptyString(item.submittedAt) ||
    Number.isNaN(Date.parse(item.submittedAt as string)) ||
    (item.steer !== undefined && typeof item.steer !== 'boolean')
  ) {
    return false;
  }
  if (item.preflight !== undefined) {
    if (
      !item.preflight ||
      typeof item.preflight !== 'object' ||
      !isNonEmptyString((item.preflight as Record<string, unknown>).actionId) ||
      !isValidPreflightKind((item.preflight as Record<string, unknown>).kind)
    ) {
      return false;
    }
  }
  return true;
};

const validatePersistedQueue = <Snapshot>(value: unknown): PersistedQueueV1<Snapshot> | string => {
  if (!value || typeof value !== 'object') return 'record must be an object';
  const record = value as Record<string, unknown>;
  if (record.version !== 1) return 'unsupported queue record version';
  if (!Number.isSafeInteger(record.nextSequence) || (record.nextSequence as number) < 1) return 'invalid next sequence';
  if (!Array.isArray(record.queue) || !(record.queue as unknown[]).every(isPersistedQueueItem))
    return 'invalid queued item';
  const queue = record.queue as PersistedQueueItem[];
  if (queue.some((item, index) => index > 0 && item.sequence <= queue[index - 1]!.sequence)) {
    return 'queue sequences must be strictly increasing';
  }
  if (queue.some((item) => item.sequence >= (record.nextSequence as number)))
    return 'next sequence must exceed queue sequences';
  if (new Set(queue.map((item) => item.id)).size !== queue.length) return 'queue item IDs must be unique';
  if (record.pause !== undefined) {
    if (
      !record.pause ||
      typeof record.pause !== 'object' ||

      typeof record.pause !== 'object' ||
      !isPauseReason((record.pause as Record<string, unknown>).reason)
    ) {
      return 'invalid pause record';
    }
  }
  if (record.active !== undefined) {
    if (!record.active || typeof record.active !== 'object') return 'invalid active record';
    const active = record.active as Record<string, unknown>;
    if (!isNonEmptyString(active.executionId) || !isPersistedQueueItem(active.item) || !('snapshot' in active))
      return 'invalid active ownership';
    if (!['running', 'awaiting_active_action', 'cancelling', 'completing'].includes(active.phase as string))
      return 'invalid active phase';
    if (active.pendingAction !== undefined) {
      if (
        !active.pendingAction ||
        typeof active.pendingAction !== 'object' ||
        !isNonEmptyString((active.pendingAction as Record<string, unknown>).actionId) ||
        !isValidActiveActionKind((active.pendingAction as Record<string, unknown>).kind)
      ) {
        return 'invalid active action';
      }
    }
    if (queue.some((item) => item.id === (active.item as PersistedQueueItem).id)) return 'active item is also queued';
  }
  return value as PersistedQueueV1<Snapshot>;
};

const persistedItemToQueueItem = (item: PersistedQueueItem): QueueItem =>
  freeze({
    ...item,
    id: item.id as ItemId,
    preflight: item.preflight
      ? { actionId: item.preflight.actionId as ActionId, kind: item.preflight.kind }
      : undefined,
  });

const queueItemToPersisted = (item: QueueItem): PersistedQueueItem => ({
  id: item.id,
  text: item.text,
  sequence: item.sequence,
  submittedAt: item.submittedAt,
  ...(item.steer ? { steer: true } : {}),
  preflight: item.preflight ? { actionId: item.preflight.actionId, kind: item.preflight.kind } : undefined,
});

type InternalPhase =
  | 'idle'
  | 'awaiting_preflight'
  | 'running'
  | 'awaiting_active_action'
  | 'cancelling'
  | 'completing'
  | 'paused';

export class QueueController<Snapshot, Terminal = unknown> {
  readonly #driver: QueueTurnDriver<Snapshot>;
  readonly #snapshotFactory: (item: QueueItem) => Snapshot;
  readonly #capacity: number;
  readonly #itemId: () => string;
  readonly #executionId: () => string;
  readonly #actionId: () => string;
  readonly #now: () => string;
  readonly #completionBarrier?: (event: Extract<TurnEvent<Terminal>, { kind: 'completed' }>) => void | Promise<void>;
  readonly #persistence?: QueuePersistence<Snapshot>;
  readonly #preflightEvaluator?: (item: QueueItem) => { preflight: { actionId: ActionId; kind: PreflightKind } } | null;
  #nextSequence = 1;
  #queue: QueueItem[] = [];
  #phase: InternalPhase = 'idle';
  #active: ActiveExecution<Snapshot> | undefined;
  #pendingAction: { actionId: ActionId; kind: ActiveActionKind } | undefined;
  #pauseReason: QueuePauseReason | undefined;
  #recovery: QueueRecovery | undefined;
  #persistenceWrites = Promise.resolve();
  /** Out-of-band occupancy (manual compaction) that must not start queued work. */
  #dispatchHeld = false;
  #cancellationUnproven = false;
  #cancellationExecutionId: ExecutionId | null = null;
  #cancelRetainedItemIds = new Set<ItemId>();

  constructor(options: QueueControllerOptions<Snapshot, Terminal>) {
    this.#driver = options.driver;
    this.#snapshotFactory = options.snapshotFactory;
    this.#capacity = options.capacity ?? Infinity;
    this.#itemId = options.ids?.item ?? (() => crypto.randomUUID());
    this.#executionId = options.ids?.execution ?? (() => crypto.randomUUID());
    this.#actionId = options.ids?.action ?? (() => crypto.randomUUID());
    this.#now = options.now ?? (() => new Date().toISOString());
    this.#completionBarrier = options.completionBarrier;
    this.#persistence = options.persistence;
    this.#preflightEvaluator = options.preflightEvaluator;
    this.#restore();
  }

  /**
   * Prevent `#dispatch` while idle. Submissions still enqueue. Returns false
   * when the queue is already occupied (running, paused, or already held).
   */
  holdDispatch(): boolean {
    if (this.#dispatchHeld || this.#phase !== 'idle' || this.#active) return false;
    this.#dispatchHeld = true;
    return true;
  }

  isDispatchHeld(): boolean {
    return this.#dispatchHeld;
  }

  /**
   * Drop the hold. By default the next queued item starts. `pauseIfQueued`
   * matches stop-during-a-turn: retained work stays paused instead of running.
   */
  releaseDispatch(options: { pauseIfQueued?: boolean } = {}): void {
    if (!this.#dispatchHeld) return;
    this.#dispatchHeld = false;
    if (options.pauseIfQueued && this.#queue.length > 0 && this.#phase === 'idle' && !this.#active) {
      this.#phase = 'paused';
      this.#pauseReason = 'manual';
      void this.#persist();
      return;
    }
    void this.#dispatch();
  }

  state(): QueueState<Snapshot> {
    const queue = this.#queue.map((item) => ({ ...item }));
    const recovery = this.#recovery ? { recovery: this.#recovery } : {};

    if (this.#phase === 'awaiting_preflight') {
      return freeze({
        kind: 'awaiting_preflight',
        queue,
        head: { ...queue[0]! },
        ...recovery,
      });
    }
    if (this.#phase === 'awaiting_active_action') {
      return freeze({
        kind: 'awaiting_active_action',
        queue,
        active: this.#active!,
        pendingAction: this.#pendingAction!,
        ...recovery,
      });
    }
    if (this.#phase === 'paused') return freeze({ kind: 'paused', queue, reason: this.#pauseReason!, ...recovery });
    if (this.#phase === 'cancelling') return freeze({ kind: 'cancelling', queue, active: this.#active!, ...recovery });
    if (this.#phase === 'completing') return freeze({ kind: 'completing', queue, active: this.#active!, ...recovery });
    if (this.#active) return freeze({ kind: 'running', queue, active: this.#active, ...recovery });
    return freeze({ kind: 'idle', queue, ...recovery });
  }

  async command(cmd: QueueCommand): Promise<QueueCommandResult> {
    switch (cmd.kind) {
      case 'submit':
        return this.#submit(cmd);
      case 'steer':
        return this.#submit(cmd);
      case 'cancel':
        return this.#cancel();
      case 'cancellation_settled': {
        if (
          this.#phase !== 'cancelling' ||
          !this.#cancellationUnproven ||
          this.#active?.executionId !== cmd.executionId ||
          this.#cancellationExecutionId !== cmd.executionId
        ) {
          return { kind: 'no_op' };
        }
        this.#active = undefined;
        this.#pendingAction = undefined;
        this.#cancellationUnproven = false;
        this.#cancellationExecutionId = null;
        if (this.#cancelRetainedItemIds.size === 0) {
          this.#phase = 'idle';
          this.#pauseReason = undefined;
        } else {
          this.#phase = 'paused';
          this.#pauseReason = 'manual';
        }
        this.#cancelRetainedItemIds.clear();
        await this.#persist();
        if (this.#phase === 'idle') await this.#dispatch();
        return { kind: 'accepted' };
      }
      case 'answer_preflight': {
        if (this.#phase !== 'awaiting_preflight') return { kind: 'rejected', reason: 'stale' };
        const head = this.#queue[0]!;
        if (head.id !== cmd.itemId || head.preflight?.actionId !== cmd.actionId) {
          return { kind: 'rejected', reason: 'stale' };
        }
        if (!cmd.accepted) {
          this.#queue.shift();
          this.#phase = 'idle';
          await this.#persist();
          await this.#dispatch();
          return { kind: 'accepted' };
        }
        return this.#acceptPreflight();
      }
      case 'resolve_tool_approval': {
        if (this.#phase !== 'awaiting_active_action') return { kind: 'rejected', reason: 'stale' };
        if (
          this.#active!.executionId !== cmd.executionId ||
          this.#pendingAction!.actionId !== cmd.actionId ||
          this.#pendingAction!.kind !== 'tool_approval'
        ) {
          return { kind: 'rejected', reason: 'stale' };
        }
        return this.#resolveAction();
      }
      case 'answer_ask_user': {
        if (this.#phase !== 'awaiting_active_action') return { kind: 'rejected', reason: 'stale' };
        if (
          this.#active!.executionId !== cmd.executionId ||
          this.#pendingAction!.actionId !== cmd.actionId ||
          this.#pendingAction!.kind !== 'ask_user'
        ) {
          return { kind: 'rejected', reason: 'stale' };
        }
        return this.#resolveAction();
      }
      case 'resume_queue':
        if (this.#phase !== 'paused') return { kind: 'no_op' };
        this.#phase = 'idle';
        this.#pauseReason = undefined;
        await this.#persist();
        await this.#dispatch();
        return { kind: 'accepted' };
      case 'discard_queue':
        this.#queue = [];
        if (this.#phase === 'cancelling') {
          // Discarding retained work during cancellation changes the stop's
          // effective retention decision, but never releases active ownership.
          this.#cancelRetainedItemIds.clear();
        }
        this.#releaseEmptyPause();
        await this.#persist();
        return { kind: 'accepted' };
      case 'edit_queued': {
        const index = this.#queue.findIndex((item) => item.id === cmd.itemId);
        if (index < 0 || !cmd.text.trim()) return { kind: 'rejected', reason: index < 0 ? 'not_queued' : 'invalid' };
        this.#queue[index] = freeze({ ...this.#queue[index], text: cmd.text });
        await this.#persist();
        return { kind: 'accepted' };
      }
      case 'remove_queued': {
        const index = this.#queue.findIndex((item) => item.id === cmd.itemId);
        if (index < 0) return { kind: 'rejected', reason: 'not_queued' };
        this.#queue.splice(index, 1);
        this.#releaseEmptyPause();
        if (this.#phase === 'cancelling') {
          this.#cancelRetainedItemIds.delete(cmd.itemId);
        }
        if (this.#phase === 'awaiting_preflight' && index === 0) {
          this.#phase = 'idle';
        }
        await this.#persist();
        if (this.#phase === 'idle') {
          await this.#dispatch();
        }
        return { kind: 'accepted' };
      }
      case 'change_execution_settings':
      case 'change_cosmetic_settings':
        await this.#persist();
        return { kind: 'accepted' };
    }
  }

  async #submit(cmd: Extract<QueueCommand, { kind: 'submit' | 'steer' }>): Promise<QueueCommandResult> {
    if (!cmd.text.trim()) return { kind: 'rejected', reason: 'invalid' };
    if (this.#queue.length >= this.#capacity) return { kind: 'rejected', reason: 'capacity' };
    const id = cmd.id ?? this.#itemId();
    if (!isNonEmptyString(id) || this.#queue.some((item) => item.id === id) || this.#active?.item.id === id) {
      return { kind: 'rejected', reason: 'invalid' };
    }
    const item = freeze({
      id: id as ItemId,
      text: cmd.text,
      sequence: this.#nextSequence++,
      submittedAt: this.#now(),
      ...(cmd.kind === 'steer' ? { steer: true as const } : {}),
    });
    if (cmd.kind === 'steer') {
      // A steer that reaches the queue could not be delivered into the running
      // turn, so it runs as its own turn — ahead of the follow-ups queued
      // before it, which is the priority the user expressed by steering, and
      // behind steers they sent earlier, which is the order they said it in.
      const firstFollowUp = this.#queue.findIndex((queued) => !queued.steer);
      const insertAt = firstFollowUp < 0 ? this.#queue.length : firstFollowUp;
      this.#queue = [...this.#queue.slice(0, insertAt), item, ...this.#queue.slice(insertAt)].map((queued) =>
        freeze({ ...queued, sequence: this.#nextSequence++ }),
      );
      await this.#persist();
      await this.#dispatch();
      return { kind: 'accepted' };
    }
    this.#queue.push(item);
    await this.#persist();
    await this.#dispatch();
    return { kind: 'accepted' };
  }

  async event(event: TurnEvent<Terminal>): Promise<void> {
    if (event.kind === 'tool_approval_requested' || event.kind === 'ask_user_requested') {
      if (!this.#active || this.#active.executionId !== event.executionId || this.#phase !== 'running') return;
      this.#pendingAction = {
        actionId: event.actionId,
        kind: event.kind === 'tool_approval_requested' ? 'tool_approval' : 'ask_user',
      };
      this.#phase = 'awaiting_active_action';
      await this.#persist();
      return;
    }

    if (!this.#active || this.#active.executionId !== event.executionId) return;

    const activeFromPhase = this.#phase === 'running' || this.#phase === 'awaiting_active_action';
    if (!activeFromPhase) return;

    if (event.kind === 'failed') {
      this.#active = undefined;
      this.#pendingAction = undefined;
      // Failure policy: do not auto-advance. Pause with retained work so the
      // user can resume or discard; only return to idle when nothing remains.
      if (this.#queue.length === 0) {
        this.#phase = 'idle';
        this.#pauseReason = undefined;
      } else {
        this.#phase = 'paused';
        this.#pauseReason = 'failure';
      }
      await this.#persist();
      return;
    }
    if (event.kind !== 'completed') return;

    this.#pendingAction = undefined;
    this.#phase = 'completing';
    await this.#persist();
    await this.#completionBarrier?.(event);
    if (this.#phase !== 'completing' || this.#active?.executionId !== event.executionId) return;
    this.#active = undefined;
    this.#phase = 'idle';
    await this.#persist();
    await this.#dispatch();
  }

  async #resolveAction(): Promise<QueueCommandResult> {
    this.#phase = 'running';
